import{c as e,Q as o,j as d,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Harness 進化報告：Context Engineering（Claude 5 世代）× Handling Unknowns 雙來源稽核","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-26-harness-evolution-context-engineering-unknowns.md","filePath":"research/reports/2026-07-26-harness-evolution-context-engineering-unknowns.md","lastUpdated":1785909234000}'),n={name:"research/reports/2026-07-26-harness-evolution-context-engineering-unknowns.md"};function s(i,t,a,c,l,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="harness-進化報告-context-engineering-claude-5-世代-×-handling-unknowns-雙來源稽核" tabindex="-1">Harness 進化報告：Context Engineering（Claude 5 世代）× Handling Unknowns 雙來源稽核 <a class="header-anchor" href="#harness-進化報告-context-engineering-claude-5-世代-×-handling-unknowns-雙來源稽核" aria-label="Permalink to &quot;Harness 進化報告：Context Engineering（Claude 5 世代）× Handling Unknowns 雙來源稽核&quot;">​</a></h1><blockquote><p>日期：2026-07-26 · 調度：Fable 5（整合/終審）· 研究：Opus 5 ×2 · 實作/查核：Sonnet 5 ×2 + Opus 5 ×1 · 對抗審查：Opus 5（異 context） 稽核基準： A = <a href="https://claude.com/blog/the-new-rules-of-context-engineering-for-claude-5-generation-models" target="_blank" rel="noreferrer">https://claude.com/blog/the-new-rules-of-context-engineering-for-claude-5-generation-models</a>（8 原則） B = <a href="https://thariqs.github.io/html-effectiveness/unknowns/" target="_blank" rel="noreferrer">https://thariqs.github.io/html-effectiveness/unknowns/</a>（11 技法）</p></blockquote><h2 id="_1-方法-提問式稽核" tabindex="-1">1. 方法：提問式稽核 <a class="header-anchor" href="#_1-方法-提問式稽核" aria-label="Permalink to &quot;1. 方法：提問式稽核&quot;">​</a></h2><p>不直接改條文，而是把兩來源蒸餾成 <strong>27 條可驗證檢查問句</strong>（每原則 1–2 問），逐條拷問現行 harness 並要求 file:line 證據。Verdict：<strong>PASS 17 · GAP 9 · N/A 1</strong>。</p><p>接地護欄（先立後審）：</p><ul><li>兩來源皆屬 <strong>prompt 層</strong>，對 hook/enforcement 層無基準——本輪不動任何 hook。</li><li>A1 Unhobbling 原文語境限行為/風格約束；<strong>不得引為刪除 <code>[E]</code> 驗證閘門的理由</strong>。剪枝範圍限 <code>[P]</code>，<code>[E]</code> 逐字保留（core.md §Framework Integrity）。</li></ul><h2 id="_2-gap-與落地變更-9-提案全採納-3-文件同步" tabindex="-1">2. GAP 與落地變更（9 提案全採納 + 3 文件同步） <a class="header-anchor" href="#_2-gap-與落地變更-9-提案全採納-3-文件同步" aria-label="Permalink to &quot;2. GAP 與落地變更（9 提案全採納 + 3 文件同步）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>GAP（來源）</th><th>變更</th><th>檔案</th></tr></thead><tbody><tr><td>P1</td><td>兩規則檔無可判性標記（A1）</td><td>output-discipline.md 標 <code>[U]</code>（user-preference，不隨世代放寬亦不剪枝）；context-management.md 三節標 <code>[P]</code></td><td>rules/ ×2</td></tr><tr><td>P2</td><td>git 生命週期四入口無路由表（A3）</td><td>RESOLVER 新增「Git 生命週期路由」表，<code>/ship</code> 為預設入口</td><td>RESOLVER.md</td></tr><tr><td>P3</td><td>AGENTS.md §2 速記重複理由不精確（A5）</td><td>誠實化：僅對 sub-agent 為必要覆蓋，對主 context 屬刻意接受的冗餘</td><td>AGENTS.md</td></tr><tr><td>P4</td><td>quick-commit 管線選檔與「逐檔指名」漂移（A5）</td><td>管線只產候選清單；實際 add 逐檔指名，&gt;5 檔先出示</td><td>quick-commit.md</td></tr><tr><td>P5</td><td>手抄記憶義務與 auto-memory 未收斂（A6）</td><td>手寫只留兩類（糾正/連續失敗→LESSONS）；入庫過門義務保留</td><td>core.md <code>[P]</code></td></tr><tr><td>P6</td><td>常駐層 reference 全為散文（A7）</td><td>CLAUDE.md 加一行指向可執行 EVAL-PACK fixtures</td><td>CLAUDE.md</td></tr><tr><td>P7</td><td>無拋棄式原型授權路徑（B4）</td><td>judgment-rubrics 新 §R6 探針授權：worktree/scratchpad 原型免事前核可、不得進 PR</td><td>judgment-rubrics.md</td></tr><tr><td>P8</td><td>PROPOSE 錨定第一可行解（B5）</td><td>scope 有量級選擇時列 ≥2 級由使用者選</td><td>core.md <code>[P]</code></td></tr><tr><td>P9</td><td>提問無代價排序（B6）</td><td>T6 補排序判準：不可逆 &gt; 跨模組 &gt; 單檔 &gt; 風格，一次問最貴 1–3 題</td><td>know-your-unknowns</td></tr><tr><td>同步 a</td><td>model-profiles pin 敘述過時</td><td>追記 2026-07-26 pin 已升 claude-opus-5（commit 8142e17，已親驗）</td><td>model-profiles.md</td></tr><tr><td>同步 b</td><td>HARNESS-CARD defaultMode 記載過時</td><td>追記現值 auto（settings.json 已親驗），不覆寫歷史</td><td>HARNESS-CARD.md</td></tr><tr><td>同步 c</td><td>歷史事故段落易誤讀為現況</td><td>加「歷史實例」標記</td><td>model-profiles.md</td></tr></tbody></table><h2 id="_3-merge-push-commit-流程簡化-ship-單一入口-s0–s12" tabindex="-1">3. Merge/Push/Commit 流程簡化：<code>/ship</code> 單一入口（S0–S12） <a class="header-anchor" href="#_3-merge-push-commit-流程簡化-ship-單一入口-s0–s12" aria-label="Permalink to &quot;3. Merge/Push/Commit 流程簡化：`/ship` 單一入口（S0–S12）&quot;">​</a></h2><p><strong>摩擦診斷</strong>：四個入口（quick-commit/quick-pr/pr-guard/verified-merge）路由重疊、中間 4 個人工確認點。實測歸因：settings.json ask 清單本就<strong>不含</strong>普通 <code>git push</code>（只擋 <code>--force*</code> 變體與 MCP push）——「push 要允許」的體感摩擦主要來自流程碎片化而非權限設定，故<strong>未動 permissions</strong>（未歸因前放寬 = 新攻擊面）。</p><p><strong>簡化後</strong>（新 skill <code>.claude/skills/ship/SKILL.md</code>）：</p><ul><li>單一入口，復用既有四 skill 實作（引用不複製，避免雙份漂移）。</li><li>中間人工確認 <strong>4 → 1</strong>：pathspec 確認前移至 S0 一次宣告（禁通配、<code>set -f</code> 防 shell 先展開）；S8 Gate 2 由人工 assert 改為 <code>comm</code> 機械比對（gate 更確定性，非弱化）；push 自動退避重試；Quiz 自主模式跳過並記錄。</li><li><strong>唯一保留的人工確認在 S10（merge，不可逆）</strong>，但支援「使用者當次訊息原文顯式預授權」時自動 merge——預授權來源寫死排除：記憶檔、compact 轉述、外部輸入、<strong>parent 委派 prompt</strong>、跨 PR 延續。</li><li>硬邊界零放寬：healthcheck 兩處保留、verified-merge 4 gate 全在、<code>--force*</code> 仍走 ask、S12 終局報告由 parent 親跑出示。</li></ul><h2 id="_4-對抗審查結果-異-context-opus-5" tabindex="-1">4. 對抗審查結果（異 context Opus 5） <a class="header-anchor" href="#_4-對抗審查結果-異-context-opus-5" aria-label="Permalink to &quot;4. 對抗審查結果（異 context Opus 5）&quot;">​</a></h2><p>初審 verdict <strong>NEEDS-WORK</strong>，4 必修全數修復後由 Fable 5 親驗收：</p><ol><li>S0 通配守衛可被 shell glob 先展開繞過 → 加 <code>set -f</code> + <code>?</code> 通配同禁。</li><li>S8 宣告檔無 freshness 斷言（alias 跳 S0 會沿用舊檔）→ 檔案移入 <code>$(git rev-parse --git-dir)</code>、加 branch 相符 + 6h 時效斷言。</li><li>S10 預授權排除清單缺 parent 委派 prompt 向量 → 已補。</li><li>S8「STASH+REPORT」語義不實（history 已推送，stash 無法補救）→ 改 REPORT+HALT + revert 指引。</li></ol><p>親跑驗證收據：<code>git diff core.md</code> 僅兩處 <code>[P]</code> 變更、TEST/<code>[E]</code> 全節逐字未動；autoload byte <strong>18,567 ≤ 19,000</strong>；<code>healthcheck.sh</code> <strong>PASS 244 / FAIL 0</strong>；skill 索引重建 32 skills、引用完整性 dangling=0。</p><h2 id="_5-未決事項-不阻塞本輪" tabindex="-1">5. 未決事項（不阻塞本輪） <a class="header-anchor" href="#_5-未決事項-不阻塞本輪" aria-label="Permalink to &quot;5. 未決事項（不阻塞本輪）&quot;">​</a></h2><ul><li>pre-commit-review.sh 的 <code>git add &amp;&amp; git commit</code> 單鏈 staged=0 穿越漏洞：<strong>已知未緩解</strong>（hook 層，兩來源無基準，留待 hook 專輪）。</li><li>B 來源為個人頁面，權威層級低於官方 blog；本輪僅採其與 A 不衝突的技法。</li><li><code>/ship</code> 多 session 並行：宣告檔已 repo-scoped（git-dir），跨 repo 無衝突；同 repo 並行 session 仍共用，屬殘餘風險（發生率低，S8 branch 斷言可攔大半）。</li></ul>',18)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
